const sectionContext: Record<string, string> = {
  '01': 'Start with the operating system: demand enters, capacity constrains, decisions allocate resources, and OEE reveals how planned time becomes good output.',
  '02': 'Capacity becomes a promise through the planning chain: forecast and orders → MPS → BOM explosion → MRP → release and dispatch.',
  '03': 'Inventory is a service decision under uncertainty. The right question is not “how much stock?” but “what service level is worth its total cost?”',
  '04': 'Waiting is a system outcome. Capacity, variability, and discipline interact; utilization near 100% can make delay explode.',
  '05': 'Layout and balancing turn a process model into physical movement. Flow, adjacency, precedence, and safety must be designed together.',
  '06': 'The supply chain is a network, not a sequence of isolated departments. Local optimization can amplify variability upstream.',
  '07': 'Maintenance protects function over the asset life cycle. Failure data, reliability distributions, and economics should drive the policy.',
  '08': 'Work measurement converts observation into a fair, reproducible standard—only after method, pace, allowance, and uncertainty are made explicit.',
}

const sectionTakeaways: Record<string, string> = {
  '01': 'Capacity is a system promise: never discuss utilization without naming time basis, capacity definition, quality, and the bottleneck.',
  '02': 'MPS, MRP, and dispatching are one chain. A schedule is only feasible when material, capacity, and priority agree.',
  '03': 'Every inventory rule is a trade-off among purchase, ordering, holding, shortage, and service-level cost.',
  '04': 'The closer utilization gets to one, the more valuable variability reduction and capacity buffers become.',
  '05': 'A good layout minimizes total system friction—not just distance—while protecting safety, flexibility, and information flow.',
  '06': 'Measure the network end-to-end: service, cash, inventory, variability, and resilience must be read together.',
  '07': 'The best maintenance policy follows failure behavior and consequence; “preventive” is not automatically optimal.',
  '08': 'A standard time is a documented model of a method and condition, not a permanent label attached to a person.',
}

