const workedExamples: Record<string, { title: string; steps: string[]; result: string }> = {
  '01': { title: 'OEE and load ratio — one work centre', steps: ['Planned production time = 420 min; run time = 360 min; total count = 180; good count = 171; ideal cycle = 2 min.', 'Availability = 360 / 420 = 85.7%; Performance = (2 × 180) / 360 = 100%; Quality = 171 / 180 = 95.0%.', 'Required CRP load = 460 min against 420 min available.'], result: 'OEE = 85.7% × 100% × 95.0% = 81.4%; load ratio = 460 / 420 = 109.5%, so the work centre is overloaded.' },
  '02': { title: 'MPS → POH → ATP', steps: ['Beginning inventory = 60 units. Forecast: 90 / 110 / 100. Customer orders: 80 / 120 / 70. MPS: 100 / 120 / 100.', 'POH₁ = 60 + 100 − 90 = 70; POH₂ = 70 + 120 − 120 = 70; POH₃ = 70 + 100 − 100 = 70.', 'ATP in period 1 = 60 + 100 − 80 = 80 units before the next MPS receipt.'], result: 'The plan protects a 70-unit projected balance while leaving 80 units available to promise in period 1.' },
  '03': { title: 'EOQ and reorder point', steps: ['D = 10,000 units/year; S = $40/order; H = $2/unit-year. EOQ = √(2 × 10,000 × 40 / 2) = 632 units.', 'Annual ordering cost = (10,000 / 632) × $40 ≈ $632; annual holding cost = (632 / 2) × $2 ≈ $632.', 'Average demand = 40/day; lead time = 5 days; safety stock = 60 units.'], result: 'ROP = 40 × 5 + 60 = 260 units. EOQ balances ordering and holding cost; ROP protects service.' },
  '04': { title: 'M/M/1 waiting cost', steps: ['Arrival rate λ = 8 customers/hour; service rate μ = 10/hour; utilization ρ = 0.8.', 'L = 8 / (10 − 8) = 4 customers; Lq = 8² / [10(10 − 8)] = 3.2 customers.', 'W = 1 / (10 − 8) = 0.5 hour; Wq = 0.4 hour; P₀ = 0.2; P₃ = (1 − 0.8) × 0.8³ = 0.1024.'], result: 'A two-minute change in service capacity can materially reduce waiting because the curve is non-linear near ρ = 1.' },
  '05': { title: 'Line balance', steps: ['Task time = 42 min; demand requires 6 stations; cycle time = 8 min.', 'Theoretical minimum stations = ceil(42 / 8) = 6. Efficiency = 42 / (6 × 8) = 87.5%.', 'Balance delay = 12.5%; precedence and ergonomics still need validation.'], result: 'The line is numerically feasible, but the final layout must confirm precedence, walking, quality checks, and safety.' },
  '06': { title: 'Transportation allocation', steps: ['Two plants ship to two markets. Let xᵢⱼ be units shipped and cᵢⱼ be cost per unit.', 'Objective: minimize 4x₁₁ + 6x₁₂ + 5x₂₁ + 3x₂₂, subject to supply and demand constraints.', 'Evaluate the optimal allocation against service time, reliability, and emissions—not cost alone.'], result: 'The transportation model provides a cost-minimum baseline; the operational decision adds feasibility and resilience constraints.' },
  '07': { title: 'Weibull reliability', steps: ['β = 2, η = 1,000 hours, t = 500 hours. R(t) = exp[−(500/1,000)²].', 'R(500) = exp(−0.25) ≈ 0.779. For MTBF ≈ ηΓ(1 + 1/β) ≈ 886 hours and MTTR = 4 hours:', 'Availability ≈ 886 / (886 + 4) = 99.55%.'], result: 'Reliability at a mission time and steady-state availability answer different questions; do not substitute one for the other.' },
  '08': { title: 'Time study and work sampling', steps: ['Observed time = 5.2 min; rating = 1.10; allowance = 15%. Normal time = 5.2 × 1.10 = 5.72 min.', 'Standard time = 5.72 × 1.15 = 6.578 min. For work sampling, 138 productive observations out of 200 gives p̂ = 69%.', 'For p = 0.70, z = 1.96, e = 0.05: n = z²p(1−p)/e² ≈ 323 observations.'], result: 'The standard is traceable to method, rating, allowance, and sample confidence—not just a stopwatch average.' },
}

